#!/usr/bin/env python3
"""Builds data/sitingdash-overrides.json: SitingDash's own relabels on top of SitingIntel's feed.
Never edits data/ohio-pilot.json. Every override carries the rule id and a reason.
Re-run after SitingIntel regenerates; review the manual lists (SEVERITY, DEL_REFERENCED) by hand."""
import json, re, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FEED = json.loads((ROOT / "data/ohio-pilot.json").read_text())
VERIFIED_ON = "2026-11-13"  # PT date the SitingDash checks were done

RULES = {
    "U1": "Red flag generated by SitingIntel as 'Secondhand/unconfirmed source: …' — the flag concerns a record whose sourcing is secondhand or not verified against a primary record.",
    "U2": "SitingIntel's source dataset marks the record 'reported' (its legend: secondary/aggregator, paywalled snippet, or search summary; not independently confirmed).",
    "U3": "Delaware record named by a 'Secondhand/unconfirmed source' flag whose reason says the main claim is secondhand, single-source, or not verified.",
    "U4": "Record text (notes, decision, label, summary, date) itself says the content is unverified / not verified / secondhand / as quoted / est. / estimate / snippet / search summary / aggregator / tracker-only / unconfirmed / reportedly / (reported).",
    "H1": "HIGH — flag text states an enacted (adopted/passed/in-effect) moratorium or ban.",
    "H2": "HIGH — flag text states a denial of the project.",
    "H3": "HIGH — flag text states a ballot or referendum defeat for the project.",
    "H4": "HIGH — flag text states litigation or an appeal affecting the project.",
    "M1": "MEDIUM — flag text states a pending or proposed moratorium or ban (including one placed on, or being certified to, a ballot).",
    "M2": "MEDIUM — flag text states organized opposition with an official action scheduled.",
    "M3": "MEDIUM — flag text states a utility or water constraint documented in an official record.",
    "L1": "LOW — flag concerns commentary or social sentiment with no official action.",
    "S1": "Source added by SitingDash after checking the page with curl (non-404) and reading it.",
}

MARKER = re.compile(r"\bunverified\b|not (?:independently )?verified|not independently|secondhand|second-hand|as quoted|\best\.|\bestimate[ds]?\b|unconfirmed|search (?:summary|snippet|synthesis)|\bsnippet\b|aggregator|trackers? only|tracker only|reported only|paywalled|\breportedly\b|\(reported\b", re.I)
# Flags that only describe research access / method, not a claim about the siting record (excluded from U4).
U4_EXCLUDE = {"licking-oh-flag-16": "describes which sources were paywalled/unposted (research access), not a siting claim",
              "licking-oh-flag-18": "lists aggregator-only items that were excluded from the dataset (method note)",
              "delaware-oh-flag-14": "describes paywalled/blocked outlets (research access), not a siting claim",
              "delaware-oh-action-03": "notes mention a search-engine claim only to reject it; status 'not adopted' rests on the primary signed journal"}

DEL_REFERENCED = {  # U3, from SitingIntel's own flag reasons (delaware-oh-flag-19..34)
    "delaware-oh-outcome-01": "flag-19: address and first-building size from trackers only; capacity only a consultant estimate",
    "delaware-oh-outcome-05": "flag-21: operating status per Delaware Source only; not independently verified",
    "delaware-oh-ballot-01": "flag-22: results unofficial; article/section number reported only by Westerville News",
    "delaware-oh-vote-06": "flag-25: vote reported secondhand (Gazette, Calyx)",
    "delaware-oh-benefit-01": "flag-30: megaproject certification required for >15-yr term not verified",
    "delaware-oh-benefit-04": "flag-31: approval date reported; construction-materials exemption reported by Dispatch, not verified",
    "delaware-oh-action-02": "flag-32: 3-0 vote reported by Delaware Gazette / Calyx register; primary minutes not posted",
    "delaware-oh-action-12": "flag-34: plan adoption unverified (adoption date blank in document)",
}
# Not relabeled under U3, with reasons (U2/U4 can still apply; e.g. delaware-oh-outcome-04 is relabeled by U4):
DEL_KEPT = {
    "delaware-oh-outcome-04": "flag-20 is a contradiction between sources incl. Cologix's own page, not secondhand sourcing",
    "delaware-oh-vote-01": "flag-23: tally from primary minutes; only per-member votes inferred (rollCall left null)",
    "delaware-oh-vote-03": "flag-24: same as above",
    "delaware-oh-vote-07": "flag-26: same as above",
    "delaware-oh-vote-08": "flag-27: same as above",
    "delaware-oh-vote-09": "flag-28: primary minutes with clerical errors; still the primary record",
    "delaware-oh-sentiment-05": "flag-29: already classed inference",
    "delaware-oh-action-03": "flag-33: status 'not adopted' rests on the primary signed journal",
}

SEVERITY = {  # manual, from each flag's own title + summary
    "licking-oh-flag-09": ("high", "H4", "text: 'appeal sought in September; … filing reported 2026-10-08' (Aligned appeal)"),
    "delaware-oh-flag-25": ("high", "H1", "text: '12-month data center moratorium' + 'per-member votes inferred from \"unanimously\"' (adopted)"),
    "delaware-oh-flag-32": ("high", "H1", "text: '12-month moratorium …' + '3-0 vote reported' (adopted)"),
    "licking-oh-flag-27": ("medium", "M1", "text: 'Place >25 MW DC ban on ballot (emergency)'"),
    "licking-oh-flag-28": ("medium", "M1", "text: 'Place >25 MW DC ban on ballot'"),
    "licking-oh-flag-32": ("medium", "M1", "text: 'Ordinance submitting DC-ban charter amendment (first reading, emergency)'"),
    "delaware-oh-flag-28": ("medium", "M1", "text: 'Ord. 2026.24 certifying citizen charter amendment (data center >25 MW ban)' to the ballot"),
    "delaware-oh-flag-04": ("medium", "M1", "text: 'Berlin Township moratorium … SitingRadar lists it as \"proposed\"'"),
    "delaware-oh-flag-18": ("low", "L1", "text: social-media organizing (Facebook/X) captured; no official action stated"),
}

SOURCE_ADDS = {
    "licking-oh-flag-20": {
        "urls": [
            "https://datacenters.newalbanyohio.org/city-finances/",
            "https://www.jerseytownship.us/pdf/Resolution-26-10-19-05-Licking-County-Commissioners-CRA.pdf",
        ],
        "reason": ("City of New Albany data-center finance page (official) describes the TIF / NCA charge / income tax / PILOT "
                   "revenue formula the flag cites; Jersey Twp Res. 26-10-19-05 (official, 2-page scan) Section 1 refers to the CRA "
                   "agreement 'attached hereto as Exhibit A', which is not in the posted PDF. Both already cited elsewhere in "
                   "SitingIntel's export (licking-oh-benefit-01, -benefit-07). The 'no formal operator CBA found' part is an absence "
                   "finding and stays an inference."),
    },
}
RELATED = {
    "licking-oh-flag-15": {
        "ids": ["licking-oh-vote-07", "licking-oh-vote-08", "licking-oh-vote-10", "licking-oh-vote-11", "licking-oh-vote-12",
                "licking-oh-vote-14", "licking-oh-vote-15", "licking-oh-vote-16", "licking-oh-vote-18"],
        "reason": ("No public source URL found that directly supports a missing-records claim (an absence in SitingIntel's research). "
                   "These council-vote records, each with its own sources, show tallies without per-member votes. Note: NBC4 (Oct 2024) "
                   "reports the New Albany Microsoft abatement vote as unanimous, still without a roll call."),
    },
}

SECTIONS = ["projectOutcomes", "ballotMeasures", "councilVotes", "sentimentTimeline", "redFlags",
            "communityBenefitPrecedents", "regulatoryActions"]

def text_fields(r):
    out = {}
    for k, v in r.items():
        if k in ("id", "sourceUrl", "sourceUrls", "lastVerified", "placeholder", "sourceClass", "sourceRecordId", "sourceFactType"):
            continue
        if v is None: continue
        out[k] = v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
    return out

overrides = []
counts = {}
for county in FEED["counties"]:
    for sec in SECTIONS:
        for r in county.get(sec, []):
            rid = r["id"]
            if r.get("sourceClass") == "fact":
                rule, reason = None, None
                if sec == "redFlags" and str(r.get("title", "")).startswith("Secondhand/unconfirmed source"):
                    rule, reason = "U1", "SitingIntel flag: " + r["summary"].replace(" Kept as sourceClass 'fact' in its section.", "") + \
                        " SitingDash has also relabeled the related record where rules U2–U4 apply."
                elif r.get("sourceFactType") == "reported":
                    rule, reason = "U2", "sourceFactType 'reported' in SitingIntel's dataset."
                elif rid in DEL_REFERENCED:
                    rule, reason = "U3", DEL_REFERENCED[rid]
                elif rid not in U4_EXCLUDE:
                    for k, v in text_fields(r).items():
                        m = MARKER.search(v)
                        if m:
                            s = max(0, m.start() - 60); e = min(len(v), m.end() + 30)
                            rule, reason = "U4", f"{k} says: “…{v[s:e].strip()}…”"
                            break
                if rule:
                    overrides.append({"id": rid, "rule": rule, "set": {"sourceClass": "unconfirmed"},
                                      "was": {"sourceClass": "fact"}, "reason": reason})
                    counts[rule] = counts.get(rule, 0) + 1
            if sec == "redFlags":
                if rid in SEVERITY:
                    lvl, rule, basis = SEVERITY[rid]
                    overrides.append({"id": rid, "rule": rule, "set": {"severity": lvl, "severityClass": "inference",
                                      "severityBasis": f"{rule}: {basis}"}, "was": {"severity": r.get("severity")},
                                      "reason": RULES[rule]})
            if rid in SOURCE_ADDS:
                a = SOURCE_ADDS[rid]
                overrides.append({"id": rid, "rule": "S1", "addSourceUrls": a["urls"],
                                  "sourceNote": f"source added by SitingDash, verified {VERIFIED_ON} PT", "reason": a["reason"]})
            if rid in RELATED:
                a = RELATED[rid]
                overrides.append({"id": rid, "rule": "R1", "relatedRecords": a["ids"], "reason": a["reason"]})

doc = {
    "name": "sitingdash-overrides",
    "version": "1.0.0",
    "appliesTo": {"file": "data/ohio-pilot.json", "schema": FEED["schema"]["version"], "generatedAt": FEED["meta"]["generatedAt"]},
    "createdBy": "SitingDash", "verifiedOn": f"{VERIFIED_ON} PT",
    "notes": "Applied at render time. SitingIntel's ohio-pilot.json is not modified. Severity is always a SitingDash inference.",
    "rules": RULES | {"R1": "Related in-feed records linked by SitingDash (no external URL found)."},
    "notRelabeledUnderU3": DEL_KEPT, "u4Excluded": U4_EXCLUDE,
    "overrides": overrides,
}
(ROOT / "data/sitingdash-overrides.json").write_text(json.dumps(doc, indent=1, ensure_ascii=False) + "\n")
sev = {}
for o in overrides:
    if "severity" in o.get("set", {}): sev[o["set"]["severity"]] = sev.get(o["set"]["severity"], 0) + 1
print("relabels by rule:", counts, "total", sum(counts.values()))
print("severity:", sev)
